class MyLayer(tf.keras.layers.Layer):
    def __init__(self, units=32):
        super().__init__()
        self.units = units
    def build(self, input_shape):
        self.w = self.add_weight(shape=(input_shape[-1], self.units), initializer='random_normal')
        self.b = self.add_weight(shape=(self.units,), initializer='zeros')
    def call(self, inputs):
        return tf.matmul(inputs, self.w) + self.b

class FlexibleLayer(tf.keras.layers.Layer):
    def call(self, inputs):
        return inputs * 2

class AdaptiveLayer(tf.keras.layers.Layer):
    def build(self, input_shape):
        self.kernel = self.add_weight(shape=(input_shape[-1], 64), initializer='glorot_uniform')
    def call(self, inputs):
        return tf.matmul(inputs, self.kernel)

class CustomDense(tf.keras.layers.Layer):
    def build(self, input_shape):
        self.w = self.add_weight(shape=(input_shape[-1], 32), initializer='glorot_uniform')
    def call(self, inputs):
        return tf.matmul(inputs, self.w)

